module spi_testbench_controller(
input [3:0] STEP,
input [1:0] RANDOM_PHASE,
input [31:0] RANDOM_WORD,
output reg VALID,
output reg [2:0] ACTION,
output reg MODE,
output reg SET_MODE,
output reg [31:0] TX_WORD,
