output reg CHECK_WORD,
output reg REQUIRE_BUSY,
output reg [6:0] PULSE_LIMIT,
output reg FIXED_COUNT
);
always @* begin
VALID = 1'b0;
ACTION = 3'd0;
MODE = 1'b0;
SET_MODE = 1'b0;
TX_WORD = 32'd0;
EXPECTED_WORD = 32'd0;
CHECK_WORD = 1'b0;
REQUIRE_BUSY = 1'b0;
PULSE_LIMIT = 7'd0;
FIXED_COUNT = 1'b0;
if (RANDOM_PHASE == 2'd0) begin
if (STEP <= 4'd11) VALID = 1'b1;
if (STEP >= 4'd6 && STEP <= 4'd11) MODE = 1'b1;
case (STEP)
4'd0: ACTION = 3'd1;
4'd1: begin ACTION = 3'd2; TX_WORD = 32'h59c359c3; end
4'd2: begin ACTION = 3'd2; TX_WORD = 32'h59c359c3; EXPECTED_WORD = 32'h59c359c3; CHECK_WORD = 1'b1; end
4'd3: begin ACTION = 3'd3; SET_MODE = 1'b1; REQUIRE_BUSY = 1'b1; end
4'd4: begin ACTION = 3'd4; PULSE_LIMIT = 7'd7; FIXED_COUNT = 1'b1; end
4'd5: begin ACTION = 3'd2; TX_WORD = 32'h59c359c3; EXPECTED_WORD = 32'h9cd84392; CHECK_WORD = 1'b1; end
4'd6: begin ACTION = 3'd1; SET_MODE = 1'b1; end
4'd7: begin ACTION = 3'd2; TX_WORD = 32'h9cd84392; end
4'd8: ACTION = 3'd3;
4'd9: begin ACTION = 3'd4; PULSE_LIMIT = 7'd7; FIXED_COUNT = 1'b1; end
4'd10: begin ACTION = 3'd2; TX_WORD = 32'h9cd84392; EXPECTED_WORD = 32'h59c359c3; CHECK_WORD = 1'b1; end
4'd11: ACTION = 3'd5;
default: ;
endcase
end else begin
VALID = 1'b1;
case (RANDOM_PHASE)
2'd1: begin ACTION = 3'd1; SET_MODE = 1'b1; end
2'd2: begin ACTION = 3'd2; TX_WORD = RANDOM_WORD; end
default: begin ACTION = 3'd2; TX_WORD = RANDOM_WORD; EXPECTED_WORD = RANDOM_WORD; CHECK_WORD = 1'b1; end
endcase
end
end
endmodule

